/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.features.oauth.oidc.domain.DiscoveryContributor;
import net.civeira.phylax.features.oauth.oidc.domain.OpenIdConfiguration;

/**
 * Contributes JWKS, id-token algorithms, introspection, and revocation fields to the discovery
 * document.
 */
@ApplicationScoped
public class TokenSecurityContributor implements DiscoveryContributor {

  @Override
  public void contribute(OpenIdConfiguration.OpenIdConfigurationBuilder builder, String base) {
    builder.jwksUri(base + "jwks").idTokenSigningAlgValuesSupported(List.of("RS256"))
        .idTokenEncryptionAlgValuesSupported(List.of("RSA-OAEP"))
        .idTokenEncryptionEncValuesSupported(List.of("A256GCM"))
        .userinfoSigningAlgValuesSupported(List.of("RS256"))
        .userinfoEncryptionAlgValuesSupported(List.of("RSA-OAEP"))
        .userinfoEncryptionEncValuesSupported(List.of("A256GCM"))
        .introspectionEndpoint(base + "introspect")
        .introspectionEndpointAuthMethodsSupported(List.of("private_key_jwt", "client_secret_basic",
            "client_secret_post", "tls_client_auth", "client_secret_jwt"))
        .introspectionEndpointAuthSigningAlgValuesSupported(List.of("RS256"))
        .revocationEndpoint(base + "revocation")
        .revocationEndpointAuthMethodsSupported(List.of("private_key_jwt", "client_secret_basic",
            "client_secret_post", "tls_client_auth", "client_secret_jwt"))
        .revocationEndpointAuthSigningAlgValuesSupported(List.of("RS256"))
        .tlsClientCertificateBoundAccessTokens(true);
  }
}
